import {esc,toast} from './ui.js';
let geoPromise;
const geography=()=>geoPromise??=fetch('/shared/campus.geojson').then(r=>r.json());
let amapPromise;
function loadAMap(config){if(window.AMap)return Promise.resolve(window.AMap);return amapPromise??=new Promise((resolve,reject)=>{window._AMapSecurityConfig={serviceHost:location.origin+config.securityProxy};const s=document.createElement('script');s.src='https://webapi.amap.com/maps?v=2.0&key='+encodeURIComponent(config.amapKey);s.onload=()=>window.AMap?resolve(window.AMap):reject(Error('地图加载失败'));s.onerror=()=>reject(Error('高德地图暂时无法连接'));document.head.append(s);setTimeout(()=>reject(Error('高德地图连接超时')),12000);});}
const trust=p=>p.trust==='certified'?'已经过认证':p.trust==='community'?'社区共创点位':'地图资料点位';
export async function campusMap(element,catalog,{onPoint,onPick,trail=[]}={}){
 if(catalog.map?.provider==='amap'&&catalog.map.amapKey&&!onPick){try{return await amapMap(element,catalog,onPoint,trail);}catch(e){toast(e.message+'，已切换校园地图');}}
 const L=window.L,geo=await geography();if(!element.isConnected)return {destroy(){},trail(){},locate(){}};
 const map=L.map(element,{zoomControl:false,attributionControl:true,zoomSnap:.25,zoomDelta:.5}).setView([catalog.campus.center[1],catalog.campus.center[0]],16);
 L.control.zoom({position:'bottomright'}).addTo(map);map.attributionControl.addAttribution('<a href="https://www.openstreetmap.org/copyright" target="_blank" rel="noopener">© OpenStreetMap</a>');
 map.createPane('campus-vector');map.getPane('campus-vector').style.zIndex=350;
 const tiles=L.tileLayer('https://tile.openstreetmap.org/{z}/{x}/{y}.png',{maxZoom:19,minZoom:14});let loaded=0,failed=0;
 const notice=document.createElement('div');notice.className='map-status';notice.textContent='真实校园地图 · WGS84';element.append(notice);
 tiles.on('tileload',()=>{loaded++;notice.textContent='OpenStreetMap · 真实校园地图';});tiles.on('tileerror',()=>{failed++;if(!loaded&&failed>=3)notice.textContent='底图连接受限 · 显示已保存的真实校园地理数据';});tiles.addTo(map);
 L.geoJSON(geo,{pane:'campus-vector',style:f=>{const t=f.properties||{};return {color:t.boundary?'#ed6a37':t.highway?'#aaa798':'#9ba894',weight:t.boundary?2:t.highway?2:1,fillColor:t.building?'#d3cec3':t.leisure?'#bdcbaa':'#ecf2e6',fillOpacity:t.building?.65:t.boundary?.08:.35,dashArray:t.boundary?'6 5':undefined};}}).addTo(map);
 const boundary=L.polygon(catalog.campus.boundary.map(p=>[p[1],p[0]]),{color:'#e97148',weight:2,dashArray:'6 6',fill:false}).addTo(map);map.fitBounds(boundary.getBounds(),{padding:[28,28]});map.setMaxBounds(boundary.getBounds().pad(.65));
 const markers=new Map();for(const p of catalog.points){const marker=L.marker([p.lat,p.lng],{title:p.name,icon:L.divIcon({className:'campus-pin '+(p.trust==='community'?'community':''),html:'<span>●</span>',iconSize:[30,36],iconAnchor:[15,33]})}).addTo(map);marker.getElement()?.setAttribute('aria-label','地图点位：'+p.name);marker.bindTooltip(`${esc(p.name)}<br><small>${trust(p)}</small>`,{direction:'top',offset:[0,-24]});marker.on('click',()=>{map.panTo(marker.getLatLng());onPoint?.(p.id);});markers.set(p.id,marker);}
 let pickMarker; if(onPick)map.on('click',e=>{if(!pickMarker)pickMarker=L.marker(e.latlng,{icon:L.divIcon({className:'campus-pin selected',html:'<span>＋</span>',iconSize:[30,36],iconAnchor:[15,33]})}).addTo(map);else pickMarker.setLatLng(e.latlng);onPick({lng:e.latlng.lng,lat:e.latlng.lat});});
 const path=L.polyline(trail.map(p=>[p.lat,p.lng]),{color:'#ec6a3a',weight:4}).addTo(map);let dot,circle;
 const resize=new ResizeObserver(()=>map.invalidateSize());resize.observe(element);
 return {focus(id){const m=markers.get(id);if(m){map.setView(m.getLatLng(),18);m.openTooltip();}},trail(points){path.setLatLngs(points.map(p=>[p.lat,p.lng]));},locate(p){if(!dot){dot=L.circleMarker([p.lat,p.lng],{radius:7,color:'#fff',weight:3,fillColor:'#2879ff',fillOpacity:1}).addTo(map);circle=L.circle([p.lat,p.lng],{radius:p.accuracy,color:'#2879ff',weight:1,fillOpacity:.08}).addTo(map);}else{dot.setLatLng([p.lat,p.lng]);circle.setLatLng([p.lat,p.lng]).setRadius(p.accuracy);}if(!map.getBounds().contains([p.lat,p.lng]))toast('当前位置在校园外，轨迹仅记录校园内的位置');else map.panTo([p.lat,p.lng]);},destroy(){resize.disconnect();map.remove();}};
}
async function amapMap(element,catalog,onPoint,trail){const A=await loadAMap(catalog.map);const coords=[catalog.campus.center,...catalog.points.map(p=>[p.lng,p.lat]),...catalog.campus.boundary];const converted=await new Promise((resolve,reject)=>A.convertFrom(coords,'gps',(status,result)=>status==='complete'?resolve(result.locations):reject(Error('地图坐标转换失败'))));if(!element.isConnected)return {destroy(){}};const map=new A.Map(element,{center:converted[0],zoom:16,viewMode:'2D'});const markers=[];catalog.points.forEach((p,i)=>{const m=new A.Marker({position:converted[i+1],title:p.name,content:'<div class="amap-campus-pin">●</div>'});map.add(m);m.on('click',()=>onPoint?.(p.id));markers.push(m);});const polygon=new A.Polygon({path:converted.slice(catalog.points.length+1),strokeColor:'#ed6a37',strokeWeight:2,fillOpacity:.06});map.add(polygon);map.setFitView([polygon]);let polyline,dot;function convert(points,cb){if(!points.length)return;A.convertFrom(points.map(p=>[p.lng,p.lat]),'gps',(s,r)=>{if(s==='complete')cb(r.locations);});}function update(points){convert(points,c=>{if(!polyline){polyline=new A.Polyline({path:c,strokeColor:'#ed6a37',strokeWeight:4});map.add(polyline);}else polyline.setPath(c);});}update(trail);return{focus(id){const i=catalog.points.findIndex(p=>p.id===id);if(i>=0)map.setZoomAndCenter(18,converted[i+1]);},trail:update,locate(p){convert([p],c=>{if(!dot){dot=new A.Marker({position:c[0],content:'<div class="location-dot"></div>'});map.add(dot);}else dot.setPosition(c[0]);map.panTo(c[0]);});},destroy(){map.destroy();}};}
export function inCampus(p,campus){let inside=false;const b=campus.boundary;for(let i=0,j=b.length-1;i<b.length;j=i++){if((b[i][1]>p.lat)!==(b[j][1]>p.lat)&&p.lng<(b[j][0]-b[i][0])*(p.lat-b[i][1])/(b[j][1]-b[i][1])+b[i][0])inside=!inside;}return inside;}
